+/**
+ * Coerce loose task_create params into one or more validated `TaskDraft`s.
+ * Runtime-only tolerance for the CC TodoWrite habit of sending an ARRAY of
+ * tasks — a bare top-level array, or one under `task`/`tasks`/`todos` — without
+ * touching the cache-critical TypeBox wire schema (which stays single-object).
+ * Anything non-array delegates to `normalizeTaskDraft`.
+ */
+export function normalizeTaskDrafts(params: unknown): TaskDraft[] {
+	const items = Array.isArray(params) ? params : arrayField(params);
+	if (!items) return [normalizeTaskDraft(params)];
+	if (items.length === 0) throw new TaskParamsError("task_create received an empty task array.");
+	return items.map((item) => coerceDraft(item));
+}
+
+function arrayField(params: unknown): unknown[] | undefined {
+	if (!params || typeof params !== "object" || Array.isArray(params)) return undefined;
+	const p = params as Record<string, unknown>;
+	for (const key of ["task", "tasks", "todos"]) {
+		if (Array.isArray(p[key])) return p[key] as unknown[];
+	}
+	return undefined;
+}
